{
  "findings": [
    {
      "ref": "[D382]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, going by what parents report.",
      "stance": "neutral",
      "quote": "The short answer: yes, mostly. These ratings aren't perfect, but they're a solid starting point that can save you from accidentally buying your 8-year-old a game with graphic violence or your teen a game that's genuinely too mature even for them."
    },
    {
      "ref": "[D382]",
      "area": "content",
      "claim": "A parent reports that reviewers actually report seeing content descriptors such as \"Fantasy Violence\", \"Mild Blood\", \"Suggestive Themes\", \"Strong Language\", \"Crude Humor\", \"Use of Alcohol/Tobacco/Drugs\".",
      "stance": "neutral",
      "quote": "Common content descriptors to understand: Fantasy Violence = not realistic (cartoon fighting, magic battles); Violence = more realistic depictions; Blood = you'll see red; Intense Violence = graphic, sustained, realistic; Suggestive Themes = sexual innuendo, flirting, revealing outfits; Sexual Content = actual sexual situations; Strong Language = the F-word and similar; Crude Humor = bathroom jokes, gross-out comedy; Use of Alcohol/Tobacco/Drugs = characters using substances."
    },
    {
      "ref": "[D382]",
      "area": "data",
      "claim": "A parent reports that the app collects data for ads or shares with third parties, and that the data can be deleted.",
      "stance": "risk",
      "quote": "The rating systems aren't perfect. They tend to be more lenient with violence than with sexual content (a very American thing). They don't account for the addictive nature of some games, predatory monetization, or online toxicity."
    },
    {
      "ref": "[D382]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases, loot boxes, pay-to-win or subscription traps.",
      "stance": "risk",
      "quote": "The rating systems aren't perfect. They tend to be more lenient with violence than with sexual content (a very American thing). They don't account for the addictive nature of some games, predatory monetization, or online toxicity."
    },
    {
      "ref": "[D382]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, is it on by default, and can it be turned off.",
      "stance": "risk",
      "quote": "This is critical to understand: the rating system only covers the game content itself, not what other players might say or do. Roblox might be rated E10+, but if your kid is playing with randoms online, they could encounter inappropriate language, bullying, or worse. Fortnite is T-rated for violence, but the voice chat can be way more mature than the game itself."
    },
